function _drawEliteZoneTelegraph(X,z,now){
  if(!z||!z.r||!z.dur)return;
  const q=Math.max(0,Math.min(1,1-z.t/z.dur)),r=z.r,head=Math.max(1.5,r*q),col=z.col||'#ff2438';
  const pulse=.5+.5*Math.sin(now*.018),spin=now*.0008,mortar=z.kind==='mortar';
  X.save();X.globalCompositeOperation='source-over';
  if((mortar||col==='#ff2438')&&_pentaRed.complete&&_pentaRed.naturalWidth){
    X.save();X.translate(z.x,z.y);X.rotate(now*.00028);
    X.globalAlpha=.15+q*.13;X.drawImage(_pentaRed,-r*.88,-r*.88,r*1.76,r*1.76);X.restore();
  }
  X.globalAlpha=.15+pulse*.05;X.fillStyle=col;X.beginPath();X.arc(z.x,z.y,r,0,Math.PI*2);X.fill();
  X.globalAlpha=.82+pulse*.12;X.strokeStyle=col;X.lineWidth=2.2+pulse*1.2;X.beginPath();X.arc(z.x,z.y,r-1,0,Math.PI*2);X.stroke();
  X.globalAlpha=.70;X.lineWidth=1.4;
  for(let i=0;i<20;i++){const a=spin+Math.PI*2*i/20,len=i%5===0?8:4;X.beginPath();X.moveTo(z.x+Math.cos(a)*(r-len),z.y+Math.sin(a)*(r-len));X.lineTo(z.x+Math.cos(a)*(r+1),z.y+Math.sin(a)*(r+1));X.stroke()}
  X.globalCompositeOperation='lighter';
  X.globalAlpha=.13+pulse*.06;X.fillStyle=col;X.beginPath();X.arc(z.x,z.y,head,0,Math.PI*2);X.fill();
  X.globalAlpha=.22+pulse*.12;X.lineWidth=11;X.beginPath();X.arc(z.x,z.y,head,0,Math.PI*2);X.stroke();
  X.globalAlpha=.86+pulse*.12;X.lineWidth=3.2+pulse*1.6;X.beginPath();X.arc(z.x,z.y,head,0,Math.PI*2);X.stroke();
  X.globalAlpha=.54;X.lineWidth=1.2;X.beginPath();X.arc(z.x,z.y,Math.max(1,head-7),0,Math.PI*2);X.stroke();
  X.globalAlpha=.84;X.lineWidth=1.5;
  for(let i=0;i<12;i++){const a=spin+Math.PI*2*i/12;X.beginPath();X.moveTo(z.x+Math.cos(a)*Math.max(0,head-3),z.y+Math.sin(a)*Math.max(0,head-3));X.lineTo(z.x+Math.cos(a)*(head+6),z.y+Math.sin(a)*(head+6));X.stroke()}
  if(mortar){
    X.globalAlpha=.78;X.lineWidth=1.8;
    for(let i=0;i<4;i++){const a=spin+Math.PI*.5*i,ri=r*.38,ro=r*.55;X.beginPath();X.moveTo(z.x+Math.cos(a)*ri,z.y+Math.sin(a)*ri);X.lineTo(z.x+Math.cos(a)*ro,z.y+Math.sin(a)*ro);X.stroke()}
    X.globalAlpha=.9;X.beginPath();X.arc(z.x,z.y,5+pulse*2,0,Math.PI*2);X.stroke();
  }else{
    const s=5+pulse*2;X.globalAlpha=.95;X.beginPath();X.moveTo(z.x,z.y-s);X.lineTo(z.x+s,z.y);X.lineTo(z.x,z.y+s);X.lineTo(z.x-s,z.y);X.closePath();X.stroke();
    X.globalAlpha=.85;X.beginPath();X.arc(z.x,z.y,2.2,0,Math.PI*2);X.fill();
  }
  X.restore();
}

