function playVFXAng(id,x,y,scale,speed,ang,isSkill,alpha){
  if(!_VFX_SHEETS[id])return;
  if(_vfxAnims.length>=20){
    let vi=-1;for(let i=0;i<_vfxAnims.length;i++){if(!_vfxAnims[i].isSkill){vi=i;break}}
    if(vi<0)vi=0;
    const v=_vfxAnims[vi];v.id=id;v.x=x;v.y=y;v.frame=0;v.maxFrames=_VFX_SHEETS[id].frames;v.t=0;v.frameTime=speed||3;v.scale=scale||2.0;v.ang=ang||0;v.isSkill=!!isSkill;v.baseAlpha=alpha||0;
    _vfxAnims.push(_vfxAnims.splice(vi,1)[0]);
  }
  else _vfxAnims.push({id,x,y,frame:0,maxFrames:_VFX_SHEETS[id].frames,t:0,frameTime:speed||3,scale:scale||2.0,ang:ang||0,isSkill:!!isSkill,baseAlpha:alpha||0});
}

